from pathlib import Path

ROOT = Path.cwd()

FILES = {
    "app/(portal)/gifts/page.tsx": 'import { GiftsCatalogue } from "@/components/gifts/gifts-catalogue";\nimport { createClient } from "@/lib/supabase/server";\n\nfunction one<T>(value: T | T[] | null): T | null {\n  return Array.isArray(value) ? value[0] ?? null : value;\n}\n\nexport default async function GiftsPage() {\n  const supabase = await createClient();\n\n  const { data, error } = await supabase\n    .from("gifts")\n    .select(`\n      id,\n      name,\n      description,\n      is_general,\n      effect_mode,\n      duration_minutes,\n      muscles_modifier,\n      reflexes_modifier,\n      vigour_modifier,\n      shrewd_modifier,\n      brains_modifier,\n      presence_modifier,\n      races:gift_races(\n        race:races(\n          id,\n          name\n        )\n      ),\n      roles:gift_order_jobs(\n        role:order_jobs(\n          id,\n          name,\n          level:order_levels(\n            level,\n            order:orders(\n              id,\n              name\n            )\n          )\n        )\n      )\n    `)\n    .eq("is_active", true)\n    .order("sort_order", { ascending: true })\n    .order("name", { ascending: true });\n\n  if (error) {\n    throw new Error(\n      `Unable to load Gifts: ${error.message}`,\n    );\n  }\n\n  const gifts = (data ?? []).map((gift) => {\n    const ancestries = (gift.races ?? [])\n      .map((entry) => one(entry.race))\n      .filter(\n        (\n          race,\n        ): race is {\n          id: string;\n          name: string;\n        } => Boolean(race),\n      )\n      .map((race) => ({\n        id: race.id,\n        name: race.name,\n      }));\n\n    const roles = (gift.roles ?? [])\n      .map((entry) => {\n        const role = one(entry.role);\n        if (!role) return null;\n\n        const level = one(role.level);\n        const order = level\n          ? one(level.order)\n          : null;\n\n        return {\n          id: role.id,\n          name: role.name,\n          level: level?.level ?? null,\n          orderId: order?.id ?? null,\n          orderName: order?.name ?? null,\n        };\n      })\n      .filter(\n        (\n          role,\n        ): role is {\n          id: string;\n          name: string;\n          level: number | null;\n          orderId: string | null;\n          orderName: string | null;\n        } => Boolean(role),\n      );\n\n    return {\n      id: gift.id,\n      name: gift.name,\n      description: gift.description,\n      isGeneral: gift.is_general,\n      effectMode: gift.effect_mode as\n        | "none"\n        | "passive"\n        | "temporary",\n      durationMinutes:\n        gift.duration_minutes,\n      modifiers: {\n        muscles: gift.muscles_modifier,\n        reflexes: gift.reflexes_modifier,\n        vigour: gift.vigour_modifier,\n        shrewd: gift.shrewd_modifier,\n        brains: gift.brains_modifier,\n        presence: gift.presence_modifier,\n      },\n      ancestries,\n      roles,\n    };\n  });\n\n  return (\n    <main className="p-5 sm:p-7 lg:p-9">\n      <div className="mx-auto max-w-7xl">\n        <header className="border border-[#60482e]/45 bg-[#15100d] px-5 py-5 sm:px-6">\n          <p className="text-[8px] uppercase tracking-[0.26em] text-[#8c704b]">\n            Codex\n          </p>\n\n          <div className="mt-1 flex flex-wrap items-end justify-between gap-4">\n            <div>\n              <h1 className="font-serif text-4xl text-[#ead5ac]">\n                Gifts\n              </h1>\n\n              <p className="mt-2 max-w-3xl text-xs leading-6 text-[#9f927f]">\n                Innate, learned and bestowed capabilities available through Ancestries, Order Roles and general assignment.\n              </p>\n            </div>\n\n            <p className="text-[8px] uppercase tracking-[0.14em] text-[#766a59]">\n              {gifts.length} active Gifts\n            </p>\n          </div>\n        </header>\n\n        <GiftsCatalogue gifts={gifts} />\n      </div>\n    </main>\n  );\n}\n',
    "components/gifts/gifts-catalogue.tsx": '"use client";\n\nimport { useMemo, useState } from "react";\n\ntype GiftType =\n  | "all"\n  | "ancestry"\n  | "order"\n  | "general";\n\ntype Gift = {\n  id: string;\n  name: string;\n  description: string;\n  isGeneral: boolean;\n  effectMode:\n    | "none"\n    | "passive"\n    | "temporary";\n  durationMinutes: number | null;\n  modifiers: {\n    muscles: number;\n    reflexes: number;\n    vigour: number;\n    shrewd: number;\n    brains: number;\n    presence: number;\n  };\n  ancestries: {\n    id: string;\n    name: string;\n  }[];\n  roles: {\n    id: string;\n    name: string;\n    level: number | null;\n    orderId: string | null;\n    orderName: string | null;\n  }[];\n};\n\nfunction signed(value: number) {\n  return value > 0\n    ? `+${value}`\n    : String(value);\n}\n\nfunction effectLabel(gift: Gift) {\n  if (gift.effectMode === "passive") {\n    return "Passive";\n  }\n\n  if (gift.effectMode === "temporary") {\n    return gift.durationMinutes\n      ? `${gift.durationMinutes} min`\n      : "Temporary";\n  }\n\n  return "Gift";\n}\n\nfunction typeLabels(gift: Gift) {\n  const labels: string[] = [];\n\n  if (gift.ancestries.length) {\n    labels.push("Ancestry");\n  }\n\n  if (gift.roles.length) {\n    labels.push("Order");\n  }\n\n  if (gift.isGeneral) {\n    labels.push("General");\n  }\n\n  return labels;\n}\n\nfunction modifierLabels(gift: Gift) {\n  return [\n    ["Mus", gift.modifiers.muscles],\n    ["Ref", gift.modifiers.reflexes],\n    ["Vig", gift.modifiers.vigour],\n    ["Shr", gift.modifiers.shrewd],\n    ["Bra", gift.modifiers.brains],\n    ["Pre", gift.modifiers.presence],\n  ]\n    .filter(([, value]) => Number(value) !== 0)\n    .map(\n      ([label, value]) =>\n        `${label} ${signed(Number(value))}`,\n    );\n}\n\nexport function GiftsCatalogue({\n  gifts,\n}: {\n  gifts: Gift[];\n}) {\n  const [type, setType] =\n    useState<GiftType>("all");\n\n  const [ancestryId, setAncestryId] =\n    useState("");\n\n  const [orderId, setOrderId] =\n    useState("");\n\n  const [nameFilter, setNameFilter] =\n    useState("");\n\n  const [\n    descriptionFilter,\n    setDescriptionFilter,\n  ] = useState("");\n\n  const ancestries = useMemo(() => {\n    const byId =\n      new Map<string, string>();\n\n    for (const gift of gifts) {\n      for (\n        const ancestry\n        of gift.ancestries\n      ) {\n        byId.set(\n          ancestry.id,\n          ancestry.name,\n        );\n      }\n    }\n\n    return Array.from(\n      byId,\n      ([id, name]) => ({\n        id,\n        name,\n      }),\n    ).sort((a, b) =>\n      a.name.localeCompare(b.name),\n    );\n  }, [gifts]);\n\n  const orders = useMemo(() => {\n    const byId =\n      new Map<string, string>();\n\n    for (const gift of gifts) {\n      for (const role of gift.roles) {\n        if (\n          role.orderId &&\n          role.orderName\n        ) {\n          byId.set(\n            role.orderId,\n            role.orderName,\n          );\n        }\n      }\n    }\n\n    return Array.from(\n      byId,\n      ([id, name]) => ({\n        id,\n        name,\n      }),\n    ).sort((a, b) =>\n      a.name.localeCompare(b.name),\n    );\n  }, [gifts]);\n\n  const filtered = useMemo(() => {\n    const nameQuery =\n      nameFilter\n        .trim()\n        .toLowerCase();\n\n    const descriptionQuery =\n      descriptionFilter\n        .trim()\n        .toLowerCase();\n\n    return gifts.filter((gift) => {\n      if (\n        type === "ancestry" &&\n        gift.ancestries.length === 0\n      ) {\n        return false;\n      }\n\n      if (\n        type === "order" &&\n        gift.roles.length === 0\n      ) {\n        return false;\n      }\n\n      if (\n        type === "general" &&\n        !gift.isGeneral\n      ) {\n        return false;\n      }\n\n      if (\n        ancestryId &&\n        !gift.ancestries.some(\n          (ancestry) =>\n            ancestry.id ===\n            ancestryId,\n        )\n      ) {\n        return false;\n      }\n\n      if (\n        orderId &&\n        !gift.roles.some(\n          (role) =>\n            role.orderId === orderId,\n        )\n      ) {\n        return false;\n      }\n\n      if (\n        nameQuery &&\n        !gift.name\n          .toLowerCase()\n          .includes(nameQuery)\n      ) {\n        return false;\n      }\n\n      if (\n        descriptionQuery &&\n        !gift.description\n          .toLowerCase()\n          .includes(\n            descriptionQuery,\n          )\n      ) {\n        return false;\n      }\n\n      return true;\n    });\n  }, [\n    gifts,\n    type,\n    ancestryId,\n    orderId,\n    nameFilter,\n    descriptionFilter,\n  ]);\n\n  function reset() {\n    setType("all");\n    setAncestryId("");\n    setOrderId("");\n    setNameFilter("");\n    setDescriptionFilter("");\n  }\n\n  return (\n    <>\n      <section className="mt-4 border border-[#59432c]/45 bg-[#100c09] p-3">\n        <div className="grid gap-2 xl:grid-cols-[150px_1fr_1fr_1fr_1fr_auto]">\n          <select\n            value={type}\n            onChange={(event) =>\n              setType(\n                event.target\n                  .value as GiftType,\n              )\n            }\n            className={controlClass}\n          >\n            <option value="all">\n              All types\n            </option>\n            <option value="ancestry">\n              Ancestry\n            </option>\n            <option value="order">\n              Order\n            </option>\n            <option value="general">\n              General\n            </option>\n          </select>\n\n          <select\n            value={ancestryId}\n            onChange={(event) =>\n              setAncestryId(\n                event.target.value,\n              )\n            }\n            className={controlClass}\n          >\n            <option value="">\n              All Ancestries\n            </option>\n\n            {ancestries.map(\n              (ancestry) => (\n                <option\n                  key={ancestry.id}\n                  value={ancestry.id}\n                >\n                  {ancestry.name}\n                </option>\n              ),\n            )}\n          </select>\n\n          <select\n            value={orderId}\n            onChange={(event) =>\n              setOrderId(\n                event.target.value,\n              )\n            }\n            className={controlClass}\n          >\n            <option value="">\n              All Orders\n            </option>\n\n            {orders.map((order) => (\n              <option\n                key={order.id}\n                value={order.id}\n              >\n                {order.name}\n              </option>\n            ))}\n          </select>\n\n          <input\n            type="search"\n            value={nameFilter}\n            onChange={(event) =>\n              setNameFilter(\n                event.target.value,\n              )\n            }\n            placeholder="Filter name..."\n            className={controlClass}\n          />\n\n          <input\n            type="search"\n            value={descriptionFilter}\n            onChange={(event) =>\n              setDescriptionFilter(\n                event.target.value,\n              )\n            }\n            placeholder="Filter description..."\n            className={controlClass}\n          />\n\n          <button\n            type="button"\n            onClick={reset}\n            className="border border-[#765937]/55 bg-[#21180f] px-4 py-2 text-[8px] uppercase tracking-[0.14em] text-[#c8aa7b] transition hover:border-[#9a7445]"\n          >\n            Reset\n          </button>\n        </div>\n\n        <div className="mt-2 flex items-center justify-between gap-3 border-t border-[#59432c]/25 pt-2">\n          <p className="text-[7px] uppercase tracking-[0.12em] text-[#6f6353]">\n            A Gift may belong to more\n            than one category.\n          </p>\n\n          <p className="text-[7px] uppercase tracking-[0.12em] text-[#8a7558]">\n            {filtered.length} /{" "}\n            {gifts.length}\n          </p>\n        </div>\n      </section>\n\n      {filtered.length ? (\n        <section className="mt-3 space-y-2">\n          {filtered.map((gift) => {\n            const modifiers =\n              modifierLabels(gift);\n\n            const types =\n              typeLabels(gift);\n\n            const ancestryText =\n              gift.ancestries\n                .map(\n                  (ancestry) =>\n                    ancestry.name,\n                )\n                .join(", ");\n\n            const orderText =\n              Array.from(\n                new Set(\n                  gift.roles\n                    .map(\n                      (role) =>\n                        role.orderName,\n                    )\n                    .filter(Boolean),\n                ),\n              ).join(", ");\n\n            return (\n              <article\n                key={gift.id}\n                className="border border-[#59432c]/40 bg-[#100c09] px-4 py-3"\n              >\n                <div className="grid gap-3 lg:grid-cols-[minmax(180px,0.8fr)_minmax(260px,1.6fr)_minmax(180px,1fr)] lg:items-start">\n                  <div className="min-w-0">\n                    <div className="flex flex-wrap items-center gap-1.5">\n                      {types.map(\n                        (label) => (\n                          <span\n                            key={label}\n                            className="border border-[#60482e]/40 bg-[#17110d] px-1.5 py-0.5 text-[6px] uppercase tracking-[0.1em] text-[#9b805c]"\n                          >\n                            {label}\n                          </span>\n                        ),\n                      )}\n\n                      <span className="border border-[#60482e]/35 bg-[#17110d] px-1.5 py-0.5 text-[6px] uppercase tracking-[0.1em] text-[#746655]">\n                        {effectLabel(\n                          gift,\n                        )}\n                      </span>\n                    </div>\n\n                    <h2 className="mt-1.5 truncate font-serif text-lg text-[#dec89f]">\n                      {gift.name}\n                    </h2>\n\n                    {modifiers.length ? (\n                      <p className="mt-1 text-[7px] uppercase tracking-[0.08em] text-[#aa8c61]">\n                        {modifiers.join(\n                          " · ",\n                        )}\n                      </p>\n                    ) : null}\n                  </div>\n\n                  <p\n                    className="line-clamp-3 text-[11px] leading-5 text-[#9c8e7b]"\n                    title={\n                      gift.description\n                    }\n                  >\n                    {gift.description ||\n                      "No description."}\n                  </p>\n\n                  <div className="space-y-1 text-[8px] leading-4 text-[#7d7161]">\n                    {ancestryText ? (\n                      <p className="truncate">\n                        <span className="uppercase tracking-[0.1em] text-[#9f825b]">\n                          Ancestry:\n                        </span>{" "}\n                        {ancestryText}\n                      </p>\n                    ) : null}\n\n                    {orderText ? (\n                      <p className="truncate">\n                        <span className="uppercase tracking-[0.1em] text-[#9f825b]">\n                          Order:\n                        </span>{" "}\n                        {orderText}\n                      </p>\n                    ) : null}\n\n                    {gift.isGeneral ? (\n                      <p>\n                        <span className="uppercase tracking-[0.1em] text-[#9f825b]">\n                          General:\n                        </span>{" "}\n                        Yes\n                      </p>\n                    ) : null}\n\n                    {gift.roles.length ? (\n                      <details className="pt-0.5">\n                        <summary className="cursor-pointer text-[7px] uppercase tracking-[0.1em] text-[#91754f] hover:text-[#c3a06d]">\n                          Show linked roles\n                        </summary>\n\n                        <div className="mt-1 max-h-28 overflow-y-auto border-l border-[#59432c]/35 pl-2 text-[8px] leading-4">\n                          {gift.roles.map(\n                            (role) => (\n                              <p key={role.id}>\n                                {role.orderName\n                                  ? `${role.orderName} · `\n                                  : ""}\n                                {role.level !==\n                                null\n                                  ? `L${role.level} · `\n                                  : ""}\n                                {role.name}\n                              </p>\n                            ),\n                          )}\n                        </div>\n                      </details>\n                    ) : null}\n                  </div>\n                </div>\n              </article>\n            );\n          })}\n        </section>\n      ) : (\n        <section className="mt-3 border border-[#59432c]/40 bg-[#100c09] p-5 text-xs italic text-[#817565]">\n          No Gifts match the selected\n          filters.\n        </section>\n      )}\n    </>\n  );\n}\n\nconst controlClass =\n  "min-w-0 border border-[#59432c]/45 bg-[#15100d] px-3 py-2 text-[10px] text-[#d1bea0] outline-none placeholder:text-[#665b4d] focus:border-[#987344]";\n',
}

for rel, content in FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print("Written:", rel)

print()
print("SUCCESS")
print("Compact Gifts catalogue + filters installed.")
print("Now run: npm run build")
